plain_protocols := {"http", "ftp", "telnet", "udp", "plain", "unencrypted", "cleartext"}

insecure_protocol_patterns := ["(?i)^http$", "(?i)^ftp$", "(?i)^telnet$", "(?i)^udp$", "(?i)plain", "(?i)unencrypt", "(?i)cleartext"]

disable_security_keywords := ["disable_tls", "disable_ssl", "insecure", "skip_verify", "disable_checksum", "skip_checksum", "no_verify", "verify: false", "crc: false", "integrity_check: disabled", "validate: off", "enable_integrity: false", "use_checksum: no", "validate_certs: false", "verify_ssl: false", "verify_peer: false", "insecure_skip_verify", "strict_checking: no", "host_key_checking: false"]

integrity_field_names := {"checksum", "hash", "digest", "signature", "hmac", "integrity_check", "validate", "verify_checksum", "content-md5", "md5", "sha256", "sha512"}

protocol_attributes := {"protocol", "scheme", "transport", "url", "endpoint", "connection_string", "uri", "address", "host", "source", "destination", "broker", "server"}

secure_protocol_indicators := {"https", "sftp", "ftps", "ssh", "tls", "ssl", "ldaps", "telnets"}

is_insecure_protocol(value) {
    value.ir_type == "String"
    pattern := insecure_protocol_patterns[_]
    regex.match(pattern, value.value)
}

has_disable_security_keyword(attr_name, attr_value) {
    keyword := disable_security_keywords[_]
    regex.match(sprintf("(?i).*?%s.*?", [keyword]), attr_name)
} else {
    value.ir_type == "Boolean"
    value.value == false
    regex.match("(?i)(verify|check|validate|enable|use)", attr_name)
}

is_empty_or_null_integrity_field(attr_value) {
    attr_value.ir_type == "String"
    attr_value.value == ""
} else {
    attr_value.ir_type == "Null"
} else {
    attr_value.ir_type == "Undef"
}

is_plain_protocol_without_integrity(node) {
    attrs := glitch_lib.all_attributes(node)
    has_protocol := false
    has_integrity := false

