    attr.name == protocol_attributes[_]
    is_insecure_protocol(attr.value)
    has_protocol := true

    not has_integrity_field(node)
}

has_integrity_field(node) {
    attrs := glitch_lib.all_attributes(node)
    some attr in attrs
