package glitch

import data.glitch_lib

# Patterns for insecure protocols without integrity checks
insecure_protocol_patterns := ["http://", "ftp://", "telnet://", "unencrypted", "plain", "cleartext"]

# Attributes that indicate security verification is disabled or missing
verify_disable_patterns := ["verify.*false", "verify.*no", "verify.*disabled", "verify.*0", "check.*false", "check.*no", "check.*disabled", "check.*0", "validate.*false", "validate.*no", "validate.*disabled", "validate.*0", "skip.*verify", "insecure", "no.*verify", "gpgcheck.*0", "gpgcheck.*false"]

# Integrity-related field names
integrity_fields := {"checksum", "hash", "digest", "signature", "hmac", "integrity", "verify", "validate", "gpgcheck", "gpg_key", "md5", "sha256", "sha512", "content_md5"}

# Protocol/connection related attribute names
protocol_attrs := {"url", "source", "src", "protocol", "scheme", "endpoint", "uri", "address", "host", "connection", "broker", "server", "mirrorlist", "baseurl"}

# Check if value contains insecure protocol pattern
has_insecure_protocol(value) {
    value.ir_type == "String"
    pattern := insecure_protocol_patterns[_]
    contains(lower(value.value), pattern)
}

# Check if attribute name indicates disabled verification
is_verify_disabled(attr_name, attr_value) {
    pattern := verify_disable_patterns[_]
    regex.match(sprintf("(?i)%s", [pattern]), sprintf("%s:%s", [attr_name, get_string_value(attr_value)]))
}

get_string_value(v) = s {
    v.ir_type == "String"
    s := v.value
} else = s {
    v.ir_type == "Integer"
    s := format_int(v.value, 10)
} else = s {
    v.ir_type == "Boolean"
    s := format_int(v.value, 10)
} else = s {
    s := ""
}

# Check if value indicates disabled integrity (0, false, "", null)
is_disabled_integrity_value(v) {
    v.ir_type == "Boolean"
    v.value == false
} else {
    v.ir_type == "Integer"
    v.value == 0
} else {
    v.ir_type == "String"
    v.value == ""
} else {
    v.ir_type == "Null"
} else {
    v.ir_type == "Undef"
}

# Check if attribute is an integrity field with disabled/empty value
is_disabled_integrity_field(attr_name, attr_value) {
    integrity_fields[lower(attr_name)]
    is_disabled_integrity_value(attr_value)
}

# Walk nested structures to find key-value pairs with potential issues
walk_nested_values(node, path_prefix) = results {
    results := {{"path": sprintf("%s.%s", [path_prefix, k.value]), "key": k.value, "value": v} |
        walk(node, [_, n])
        n.ir_type == "Hash"
        item := n.value[_]
        k := item.key
        k.ir_type == "String"
        v := item.value
    }
}

# Find all nested key-value pairs in variables and attributes
all_nested_key_values(node) = kvs {
    kvs := {{"path": path, "name": name, "value": value} |
        # Direct attributes
        attrs := glitch_lib.all_attributes(node)
        attr := attrs[_]
        path := attr.name
        name := attr.name
        value := attr.value
    } union {{"path": path, "name": name, "value": value} |
        # Nested in Hash values of attributes
        attrs := glitch_lib.all_attributes(node)
        attr := attrs[_]
        nested := walk_nested_values(attr.value, attr.name)[_]
        path := nested.path
        name := nested.key
        value := nested.value
    }
}

# Also check variables for nested structures
all_variable_nested_key_values(block) = kvs {
    vars := glitch_lib.all_variables(block)
    v := vars[_]
    kvs := {{"path": v.name, "name": v.name, "value": v.value}} union {{"path": sprintf("%s.%s", [v.name, nested.key]), "name": nested.key, "value": nested.value} |
        nested := walk_nested_values(v.value, v.name)[_]
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    # Check nested key-values in the atomic unit
    kv := all_nested_key_values(au)[_]

    # Case: insecure HTTP/FTP protocol in URL/source without checksum
    protocol_attrs[lower(kv.name)]
    has_insecure_protocol(kv.value)

    # Check no integrity field exists
    not has_integrity_field_present(au)

    result := {
        "type": "sec_no_int_check",
        "element": {"ir_type": "Attribute", "name": kv.name, "value": kv.value, "line": au.line},
        "path": parent.path,
        "description": "Missing support for integrity check - Download from insecure protocol without integrity verification. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    kv := all_nested_key_values(au)[_]

    # Case: integrity verification explicitly disabled
    is_disabled_integrity_field(kv.name, kv.value)

    result := {
        "type": "sec_no_int_check",
        "element": {"ir_type": "Attribute", "name": kv.name, "value": kv.value, "line": au.line},
        "path": parent.path,
        "description": "Missing support for integrity check - Integrity verification explicitly disabled or set to empty/null. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    kv := all_nested_key_values(au)[_]

    # Case: verify/validate/check set to false/no/0
    is_verify_disabled(kv.name, kv.value)

    result := {
        "type": "sec_no_int_check",
        "element": {"ir_type": "Attribute", "name": kv.name, "value": kv.value, "line": au.line},
        "path": parent.path,
        "description": "Missing support for integrity check - Security verification explicitly disabled. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables for disabled integrity settings
    vk := all_variable_nested_key_values(parent)[_]

    is_disabled_integrity_field(vk.name, vk.value)

    result := {
        "type": "sec_no_int_check",
        "element": {"ir_type": "Variable", "name": vk.name, "value": vk.value},
        "path": parent.path,
        "description": "Missing support for integrity check - Integrity verification variable disabled or empty. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vk := all_variable_nested_key_values(parent)[_]

    protocol_attrs[lower(vk.name)]
    has_insecure_protocol(vk.value)

    # Check no integrity field in this variable structure
    not has_integrity_in_variable_structure(vk.value)

    result := {
        "type": "sec_no_int_check",
        "element": {"ir_type": "Variable", "name": vk.name, "value": vk.value},
        "path": parent.path,
        "description": "Missing support for integrity check - Variable uses insecure protocol without integrity check. (CWE-353)"
    }
}

# Helper to check if any integrity field is present and enabled
has_integrity_field_present(node) {
    kv := all_nested_key_values(node)[_]
    integrity_fields[lower(kv.name)]
    not is_disabled_integrity_value(kv.value)
}

# Helper to check if integrity field exists in variable structure
has_integrity_in_variable_structure(v) {
    walk(v, [_, n])
    n.ir_type == "Hash"
    item := n.value[_]
    item.key.ir_type == "String"
    integrity_fields[lower(item.key.value)]
    not is_disabled_integrity_value(item.value)
}

# Standalone attributes detection (top level attribute in unit block)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := parent.attributes
    attr := attrs[_]

    is_disabled_integrity_field(attr.name, attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Top-level integrity configuration disabled. (CWE-353)"
    }
}

# Check for http/ftp in remote_file, get_url, etc without checksum
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    # Common resource types that download files
    download_types := {"remote_file", "get_url", "download", "wget", "curl", "fetch", "uri"}
    download_types[lower(au.type)]

    # Check if source/url uses insecure protocol
    kv := all_nested_key_values(au)[_]
    lower(kv.name) == "source"
    has_insecure_protocol(kv.value)

    not has_integrity_field_present(au)

    result := {
        "type": "sec_no_int_check",
        "element": au,
        "path": parent.path,
        "description": "Missing support for integrity check - File download without integrity verification. (CWE-353)"
    }
}

